import React from "react";
import { DataTable, Button, ButtonGroup } from "@shopify/polaris";
import TimerStatusBadge from "./TimerStatusBadge";

const TimerTable = ({ timers, onEdit, onDelete }) => {
  const rows = timers.map((timer) => [
    timer.timerName,
    timer.promotionDescription || "-",
    timer.startDateTime,
    timer.endDateTime,
    <TimerStatusBadge
      startDateTime={timer.startDateTime}
      endDateTime={timer.endDateTime}
    />,
    <ButtonGroup segmented>
      <Button size="slim" onClick={() => onEdit(timer)}>
        Edit
      </Button>
      <Button size="slim" destructive onClick={() => onDelete(timer)}>
        Delete
      </Button>
    </ButtonGroup>,
  ]);

  return (
    <DataTable
      columnContentTypes={["text", "text", "text", "text", "text", "text"]}
      headings={[
        "Timer Name",
        "Description",
        "Start Date",
        "End Date",
        "Status",
        "Actions",
      ]}
      rows={rows}
    />
  );
};

export default TimerTable;
