import React from "react";
import { Modal, TextContainer } from "@shopify/polaris";

const DeleteTimerModal = ({ open, timer, onClose, onDelete }) => (
  <Modal
    open={open}
    onClose={onClose}
    title="Delete timer"
    primaryAction={{
      content: "Delete",
      destructive: true,
      onAction: onDelete,
    }}
    secondaryActions={[
      {
        content: "Cancel",
        onAction: onClose,
      },
    ]}
  >
    <Modal.Section>
      <TextContainer>
        <p>
          Are you sure you want to delete "{timer?.timerName}"? This action
          cannot be undone.
        </p>
      </TextContainer>
    </Modal.Section>
  </Modal>
);

export default DeleteTimerModal;
