import React, { useState, useEffect } from "react";
import { Modal, TextField, Select, FormLayout } from "@shopify/polaris";
import ColorPicker from "./ColorPicker";
import {
  formatDateForInput,
  formatTimeForInput,
  combineDateTime,
} from "../../utils/dateUtils";

const TimerModal = ({ active, timer, onClose, onSave }) => {
  const [formData, setFormData] = useState({
    timerName: "",
    startDate: "",
    startTime: "",
    endDate: "",
    endTime: "",
    promotionDescription: "",
    timerColor: "#00FF00",
    timerSize: "Medium",
    timerPosition: "Top",
    urgencyNotification: "Color pulse",
    isActive: true,
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (timer) {
      setFormData({
        timerName: timer.timerName || "",
        startDate: formatDateForInput(timer.startDateTime),
        startTime: formatTimeForInput(timer.startDateTime),
        endDate: formatDateForInput(timer.endDateTime),
        endTime: formatTimeForInput(timer.endDateTime),
        promotionDescription: timer.promotionDescription || "",
        timerColor: timer.timerColor || "#00FF00",
        timerSize: timer.timerSize || "Medium",
        timerPosition: timer.timerPosition || "Top",
        urgencyNotification: timer.urgencyNotification || "Color pulse",
        isActive: timer.isActive !== undefined ? timer.isActive : true,
      });
    } else {
      setFormData({
        timerName: "",
        startDate: "",
        startTime: "",
        endDate: "",
        endTime: "",
        promotionDescription: "",
        timerColor: "#00FF00",
        timerSize: "Medium",
        timerPosition: "Top",
        urgencyNotification: "Color pulse",
        isActive: true,
      });
    }
  }, [timer]);

  const validate = () => {
    const newErrors = {};
    if (!formData.timerName.trim())
      newErrors.timerName = "Timer name is required";
    if (!formData.startDate) newErrors.startDate = "Start date is required";
    if (!formData.startTime) newErrors.startTime = "Start time is required";
    if (!formData.endDate) newErrors.endDate = "End date is required";
    if (!formData.endTime) newErrors.endTime = "End time is required";
    if (
      formData.startDate &&
      formData.startTime &&
      formData.endDate &&
      formData.endTime
    ) {
      const start = combineDateTime(formData.startDate, formData.startTime);
      const end = combineDateTime(formData.endDate, formData.endTime);
      if (new Date(start) >= new Date(end)) {
        newErrors.endDate = "End date must be after start date";
      }
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const payload = {
        timerName: formData.timerName,
        startDateTime: combineDateTime(formData.startDate, formData.startTime),
        endDateTime: combineDateTime(formData.endDate, formData.endTime),
        promotionDescription: formData.promotionDescription,
        timerColor: formData.timerColor,
        timerSize: formData.timerSize,
        timerPosition: formData.timerPosition,
        urgencyNotification: formData.urgencyNotification,
        isActive: formData.isActive,
      };
      await onSave(payload);
      onClose();
    } catch (error) {
      // handle error
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal
      open={active}
      onClose={onClose}
      title={timer ? "Edit Timer" : "Create New Timer"}
      primaryAction={{
        content: timer ? "Update timer" : "Create timer",
        onAction: handleSubmit,
        loading,
      }}
      secondaryActions={[
        {
          content: "Cancel",
          onAction: onClose,
        },
      ]}
      large
    >
      <Modal.Section>
        <FormLayout>
          <TextField
            label="Timer name"
            value={formData.timerName}
            onChange={(value) => setFormData({ ...formData, timerName: value })}
            error={errors.timerName}
            placeholder="Enter timer name"
            requiredIndicator
          />
          <FormLayout.Group>
            <TextField
              label="Start date"
              value={formData.startDate}
              onChange={(value) =>
                setFormData({ ...formData, startDate: value })
              }
              error={errors.startDate}
              placeholder="mm/dd/yyyy"
            />
            <TextField
              label="Start time"
              value={formData.startTime}
              onChange={(value) =>
                setFormData({ ...formData, startTime: value })
              }
              error={errors.startTime}
              placeholder="--:-- --"
            />
          </FormLayout.Group>
          <FormLayout.Group>
            <TextField
              label="End date"
              value={formData.endDate}
              onChange={(value) => setFormData({ ...formData, endDate: value })}
              error={errors.endDate}
              placeholder="mm/dd/yyyy"
            />
            <TextField
              label="End time"
              value={formData.endTime}
              onChange={(value) => setFormData({ ...formData, endTime: value })}
              error={errors.endTime}
              placeholder="--:-- --"
            />
          </FormLayout.Group>
          <TextField
            label="Promotion description"
            value={formData.promotionDescription}
            onChange={(value) =>
              setFormData({ ...formData, promotionDescription: value })
            }
            multiline={4}
            placeholder="Enter promotion details"
          />
          <div>
            <label style={{ fontWeight: 500, fontSize: "14px" }}>
              Timer color
            </label>
            <ColorPicker
              value={formData.timerColor}
              onChange={(color) =>
                setFormData({ ...formData, timerColor: color })
              }
            />
          </div>
          <FormLayout.Group>
            <Select
              label="Timer size"
              options={["Small", "Medium", "Large"].map((v) => ({
                label: v,
                value: v,
              }))}
              value={formData.timerSize}
              onChange={(value) =>
                setFormData({ ...formData, timerSize: value })
              }
            />
            <Select
              label="Timer position"
              options={["Top", "Below Title", "Above Buy Button"].map((v) => ({
                label: v,
                value: v,
              }))}
              value={formData.timerPosition}
              onChange={(value) =>
                setFormData({ ...formData, timerPosition: value })
              }
            />
          </FormLayout.Group>
          <Select
            label="Urgency notification"
            options={["None", "Color pulse", "Blink", "Shake"].map((v) => ({
              label: v,
              value: v,
            }))}
            value={formData.urgencyNotification}
            onChange={(value) =>
              setFormData({ ...formData, urgencyNotification: value })
            }
          />
        </FormLayout>
      </Modal.Section>
    </Modal>
  );
};

export default TimerModal;
